  landscapeImageHref2: "https://example.com",
  landscapeImageSrc1: emailAsset("image-grids/2-col-landscape.jpg"),
  landscapeImageSrc2: emailAsset("image-grids/2-col-landscape-2.jpg"),
  landscapeSubtext1: "Accessories",
