  pageBackgroundColor: "#f1f5f9",
  portraitHeading: "Omakase",
  portraitImageAlt: "",
  portraitImageHref: "https://example.com",
  portraitImageSrc: emailAsset("image-grids/2-col-portrait-3.jpg"),
  portraitSubtext: "T-shirts and sweats",
  textColor: "#fffffe",
